// `pnpm env:local`: writes apps/web/.env.local and apps/worker/.env.local for local development
// from the running local Supabase stack (task 1.4). Both files are gitignored.
// EMAIL_CONFIRMATION_REQUIRED is copied from config.toml, so DEC63 has one local source.
// APP_SECRET and PROBE_TOKEN are new random values on every run (task 1.6). That invalidates
// open CSRF tokens and page cursors, which is harmless locally: reload the page.
// A file that was not generated by this script is never overwritten.
import { randomBytes } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import {
  emailConfirmationRequired,
  readLocalStack,
  REPO_ROOT,
  type LocalStack,
} from "./local-supabase.ts";

export const GENERATED_HEADER =
  "# Generated by `pnpm env:local` from the local Supabase stack. Local development only.";

export interface LocalSecrets {
  appSecret: string;
  probeToken: string;
}

export function newLocalSecrets(): LocalSecrets {
  return {
    appSecret: randomBytes(32).toString("base64url"),
    probeToken: randomBytes(32).toString("base64url"),
  };
}

export function webEnv(
  stack: Pick<LocalStack, "apiUrl" | "publishableKey">,
  confirmation: boolean,
  secrets: LocalSecrets = newLocalSecrets(),
): string {
  return [
    GENERATED_HEADER,
    "APP_ENV=development",
    "APP_ORIGIN=http://localhost:3000",
    `NEXT_PUBLIC_SUPABASE_URL=${stack.apiUrl}`,
    `NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=${stack.publishableKey}`,
    `EMAIL_CONFIRMATION_REQUIRED=${String(confirmation)}`,
    `APP_SECRET=${secrets.appSecret}`,
    `PROBE_TOKEN=${secrets.probeToken}`,
    "TRUSTED_PROXY_HOPS=0",
    "",
  ].join("\n");
}

export function workerEnv(): string {
  return [GENERATED_HEADER, "APP_ENV=development", ""].join("\n");
}

function write(file: string, content: string): void {
  if (existsSync(file) && !readFileSync(file, "utf8").startsWith(GENERATED_HEADER)) {
    throw new Error(`${file} exists and was not generated by pnpm env:local. Move it away first.`);
  }
  writeFileSync(file, content);
  console.log(`wrote ${file}`);
}

if (import.meta.main) {
  try {
    const stack = readLocalStack();
    write(join(REPO_ROOT, "apps", "web", ".env.local"), webEnv(stack, emailConfirmationRequired()));
    write(join(REPO_ROOT, "apps", "worker", ".env.local"), workerEnv());
  } catch (error) {
    console.error(`env:local: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  }
}
